                q(4, "[Verified Official - 2nd Annual 2023 (1SA-II 2308)] When NH₃ reacts with H⁺ to form NH₄⁺, the newly formed bond is a:", "NH₃ اور H⁺ کے درمیان بننے والا بانڈ", "Ionic bond", "Metallic bond", "Coordinate (dative) covalent bond", "Hydrogen bond", 2, "Nitrogen donates both electrons of its lone pair to H⁺.", "Coordinate Bond", true, "NBF p. 85"),
                q(5, "[Verified Official - 1st Annual 2024 (1SA-I 24005)] Which molecule contains a TRIPLE covalent bond?", "تہرا کوولینٹ بانڈ کس میں ہے", "O₂", "CO₂", "N₂", "H₂O", 2, "Each N atom shares 3 electrons → N≡N triple bond.", "Covalent Bonding", true, "NBF p. 81"),
                q(6, "Hydrogen bonding occurs when H is covalently bonded to highly electronegative:", "ہائیڈروجن بانڈنگ کن ایٹموں کے ساتھ ہوتی ہے", "C, S, or P", "F, O, or N", "Na, K, or Mg", "Cl, Br, or I only", 1, "Only tiny strongly electronegative F, O, and N create strong H-bonding.", "Hydrogen Bonding", false, "NBF p. 87"),
                q(7, "Why does solid NaCl NOT conduct electricity while molten NaCl does?", "ٹھوس NaCl بجلی کا موصل کیوں نہیں", "Solid NaCl has no ions", "Ions in solid NaCl are fixed in the lattice and cannot move", "Electrons freeze in solid NaCl", "Molten NaCl turns metallic", 1, "Electrical conduction in ionic compounds requires mobile ions.", "Ionic Properties", false, "NBF p. 88"),
                q(8, "Magnesium (2,8,2) reacts with Fluorine (2,7) to form the ionic compound:", "Mg اور F کے آئونک مرکب کا فارمولا", "MgF", "Mg₂F", "MgF₂", "Mg₂F₃", 2, "1 Mg²⁺ transfers 1 e⁻ each to two F⁻ ions → MgF₂.", "Ionic Bonding", false, "NBF p. 77"),
                q(9, "Why are metals malleable and ductile?", "دھاتوں کو پیٹ کر چادریں کیوں بنائی جا سکتی ہیں", "Cations slide smoothly within the mobile sea of electrons without repulsion", "They contain weak van der Waals molecules", "They have rigid 3D ionic lattices", "Their atoms share directional triple bonds", 0, "Non-directional metallic bonding preserves cohesion as layers shift.", "Metallic Bonding", false, "NBF p. 91"),
                q(10, "In diamond, the C–C bond length and tetrahedral angle are:", "ہیرے میں C–C بانڈ کی لمبائی اور زاویہ", "0.10 nm and 90°", "1.544 × 10⁻¹⁰ m and 109.5°", "2.50 × 10⁻¹⁰ m and 120°", "3.0 × 10⁻¹⁰ m and 180°", 1, "Textbook Table gives C–C = 1.544 × 10⁻¹⁰ m, tetrahedral 109.5°, density 3.514 g/cm³.", "Giant Covalent", false, "NBF p. 90"),
                q(11, "Which molecule is NON-POLAR covalent?", "غیر قطبی کوولینٹ مالیکیول", "HCl", "H₂O", "Cl₂", "NH₃", 2, "Two identical Cl atoms share electrons equally (ΔEN = 0).", "Polar vs Non-polar", false, "NBF p. 84"),
                q(12, "How many double covalent bonds are in one CO₂ molecule (O=C=O)?", "CO₂ میں دوہرے بانڈز کی تعداد", "0", "1", "2", "3", 2, "Carbon forms a double bond to each of the two oxygen atoms.", "Covalent Bonding", false, "NBF p. 83"),
                q(13, "In the adduct H₃N→BF₃, the electron-pair acceptor (Lewis acid) is:", "H₃N→BF₃ میں الیکٹران جوڑا قبول کرنے والا", "NH₃", "BF₃", "Both equally", "Hydrogen atom", 1, "Boron in BF₃ has only 6 valence electrons and accepts N's lone pair.", "Dative Bond", false, "NBF p. 86"),
                q(14, "Which force explains why epoxy adhesives bind strongly to wood/metal surfaces and why ice floats on water?", "ایپوکسی گوند اور برف کے تیرنے کی وجہ", "Metallic bonding", "Hydrogen bonding", "Nuclear force", "Ionic repulsion", 1, "Hydroxyl/polar groups form extensive H-bonds; ice forms an open H-bonded lattice less dense than water.", "Hydrogen Bonding", false, "NBF p. 87"),
                q(15, "Which molecule has ZERO lone pairs on its central atom?", "مرکزی ایٹم پر صفر لون پیئر", "NH₃", "H₂O", "CH₄", "HCl", 2, "Carbon in CH₄ uses all 4 valence electrons in 4 C–H single bonds.", "Covalent Bonding", false, "NBF p. 82"),
                q(16, "Which covalent substance conducts electricity well in the solid state?", "کون سا کوولینٹ ٹھوس بجلی گزارتا ہے", "Diamond", "SiO₂", "Graphite", "Solid iodine", 2, "Graphite's delocalized π electrons conduct along hexagonal sheets.", "Conductivity", false, "NBF p. 90"),
                q(17, "Aqueous HCl conducts electricity despite being a polar covalent gas because:", "HCl پانی میں بجلی کیوں گزارتا ہے", "It becomes metallic", "It ionizes in water into H₃O⁺ and Cl⁻ ions", "It melts the beaker", "It forms H₂ gas", 1, "Polar HCl dissociates completely in water into mobile ions.", "Conductivity", false, "NBF p. 89"),
