                q(19, "In HCN (H–C≡N), how many total shared electron pairs exist around Carbon?", "HCN میں کاربن کے گرد کل شریک الیکٹران جوڑے", "2", "3", "4", "1", 2, "1 pair with H + 3 pairs with N = 4 shared pairs (octet complete).", "Covalent Bonding", false, "NBF p. 83"),
                q(20, "Helium is stable with 2 valence electrons instead of 8; this rule is called:", "ہیلئیم کا 2 الیکٹران والا استحکام", "Octet rule", "Duplet rule", "Pauli rule", "Aufbau rule", 1, "Filling the 1s shell with 2 electrons achieves duplet stability.", "Duplet Rule", false, "NBF p. 74"),
                q(21, "Dipole-dipole forces exist between molecules of:", "ڈائی پول ڈائی پول قوتیں کن میں ہوتی ہیں", "H₂", "N₂", "HCl", "CH₄", 2, "Hδ⁺–Clδ⁻ is a permanent polar dipole.", "Intermolecular Forces", false, "NBF p. 86"),
                q(22, "Ionic crystals shatter when hammered because:", "ہتھوڑے سے آئونک کرسٹل کیوں ٹوٹتے ہیں", "Layers shift and bring like-charged ions face-to-face, causing repulsion", "They have delocalized electrons", "They are gases", "Their bonds are too weak", 0, "Like-charge electrostatic repulsion cleaves the crystal cleanly.", "Ionic Properties", false, "NBF p. 89"),
