                q(24, "Which compound has the lowest melting point?", "سب سے کم نقطۂ پگھلاؤ کس کا ہے", "MgO", "SiO₂", "NaCl", "CH₄", 3, "CH₄ consists of small non-polar molecules held by very weak dispersion forces.", "Table 5.1", false, "NBF p. 89"),
                q(25, "Hydronium ion (H₃O⁺) contains:", "ہائیڈرونیم آئن میں موجود بانڈز", "3 ionic bonds", "2 polar covalent + 1 coordinate covalent bond", "1 triple bond", "1 metallic bond", 1, "H₂O has 2 O–H bonds and donates 1 O lone pair to H⁺.", "Coordinate Bond", false, "NBF p. 85"),
                q(26, "Density of Diamond (Table 5.2) is:", "ہیرے کی کثافت", "1.00 g/cm³", "2.25 g/cm³", "3.514 g/cm³", "7.87 g/cm³", 2, "Tight tetrahedral packing gives diamond density 3.514 g/cm³.", "Diamond", false, "NBF p. 90"),
                q(27, "Which element tends to form an electropositive +2 cation?", "کون سا عنصر +2 کیٹائن بناتا ہے", "Oxygen (Z=8)", "Magnesium (Z=12)", "Chlorine (Z=17)", "Neon (Z=10)", 1, "Mg loses its two 3s² valence electrons.", "Electropositivity", false, "NBF p. 75"),
                q(28, "Which bond type involves a 'sea of delocalized electrons'?", "آزاد الیکٹران کا سمندر کس بانڈ میں ہوتا ہے", "Ionic", "Covalent", "Dative", "Metallic", 3, "Delocalized valence electrons glue positive metal cations together.", "Metallic Bonding", false, "NBF p. 91"),
                q(29, "Compare boiling point of H₂O (100°C) vs H₂S (−60°C). Water boils much higher due to:", "پانی کا نقطۂ ابال H₂S سے زیادہ کیوں ہے", "Ionic bonds in H₂O", "Strong hydrogen bonding between H₂O molecules", "Higher molar mass of H₂O", "Triple bonds in H₂O", 1, "O is strongly electronegative, creating H-bonds absent in H₂S.", "Hydrogen Bonding", false, "NBF p. 87"),
